pub struct Machine {
    pub balance: u64,
    pub stock: u64,
    pub refunded: u64,
}

pub fn step(s: Machine, action: u64, amount: u64) -> Machine {
    if action == 0 {
        if amount <= 18446744073709551615 - s.balance {
            Machine { balance: s.balance + amount, stock: s.stock, refunded: s.refunded }
        } else {
            s
        }
    } else if action == 1 {
        if s.balance >= 150 && s.stock > 0 {
            Machine { balance: s.balance - 150, stock: s.stock - 1, refunded: s.refunded }
        } else {
            s
        }
    } else if action == 2 {
        Machine { balance: 0, stock: s.stock, refunded: s.balance }
    } else {
        s
    }
}

