mod kernel;

use kernel::{step, Machine};
use std::io::{self, Write};

fn unsigned(text: &str) -> Result<u64, &'static str> {
    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
        return Err("非負の整数を指定してください。");
    }
    text.parse().map_err(|_| "u64の範囲を超えています。")
}

fn run() -> io::Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let stock = match args.as_slice() {
        [] => 10,
        [value] => unsigned(value).map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?,
        _ => return Err(io::Error::new(io::ErrorKind::InvalidInput, "使い方: vending-machine [初期在庫]")),
    };
    let mut s = Machine { balance: 0, stock, refunded: 0 };
    println!("自販機: 商品150円。投入 金額 / 購入 / 返金 / 表示 / 終了");
    loop {
        println!("残高: {}円 / 在庫: {}個", s.balance, s.stock);
        print!("> ");
        io::stdout().flush()?;
        let mut line = String::new();
        if io::stdin().read_line(&mut line)? == 0 {
            println!("入力終了（自動返金なし）。");
            return Ok(());
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        match parts.as_slice() {
            ["投入", value] | ["insert", value] => match unsigned(value) {
                Ok(amount) => {
                    let rejected = s.balance.checked_add(amount).is_none();
                    s = step(s, 0, amount);
                    if rejected {
                        println!("拒否: 残高がオーバーフローします。");
                    } else {
                        println!("{}円を投入しました。", amount);
                    }
                }
                Err(e) => println!("拒否: {}", e),
            },
            ["購入"] | ["buy"] => {
                let message = if s.stock == 0 { "拒否: 在庫切れです。" }
                    else if s.balance < 150 { "拒否: 残高不足です。" }
                    else { "購入成功: 商品を1個お渡しします。" };
                s = step(s, 1, 0);
                println!("{}", message);
            }
            ["返金"] | ["refund"] => {
                s = step(s, 2, 0);
                println!("返金: {}円", s.refunded);
            }
            ["表示"] | ["status"] => {}
            ["終了"] | ["quit"] => {
                println!("終了（自動返金なし）。残高: {}円 / 在庫: {}個", s.balance, s.stock);
                return Ok(());
            }
            _ => println!("拒否: 投入 金額 / 購入 / 返金 / 表示 / 終了 を入力してください。"),
        }
    }
}

fn main() {
    if let Err(e) = run() {
        eprintln!("エラー: {}", e);
        std::process::exit(1);
    }
}

