{"path":"tests/cli.rs","content":"use std::io::Write;
use std::process::{Command, Output, Stdio};

fn run(args: &[&str], input: &str) -> Output {
    let mut child = Command::new(env!("CARGO_BIN_EXE_vending-machine"))
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("start CLI");
    child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
    child.wait_with_output().unwrap()
}

fn success(args: &[&str], input: &str) -> String {
    let output = run(args, input);
    assert!(output.status.success(), "{:?}", output);
    assert!(output.stderr.is_empty(), "{:?}", output);
    String::from_utf8(output.stdout).unwrap()
}

#[test]
fn japanese_purchase_and_refunds() {
    let text = success(&["1"], "購入\n投入 200\n購入\n購入\n返金\n返金\n終了\n");
    for expected in [
        "拒否: 残高不足です。", "200円を投入しました。",
        "購入成功: 商品を1個お渡しします。", "残高: 50円 / 在庫: 0個",
        "拒否: 在庫切れです。", "返金: 50円", "返金: 0円",
        "終了（自動返金なし）。残高: 0円 / 在庫: 0個",
    ] {
        assert!(text.contains(expected), "missing {expected}: {text}");
    }
}

#[test]
fn english_aliases_and_whitespace() {
    let text = success(&[], "  insert\t150  \nbuy\nstatus\nrefund\nquit\n");
    assert!(text.contains("購入成功"));
    assert!(text.contains("返金: 0円"));
    assert!(text.contains("終了（自動返金なし）。残高: 0円 / 在庫: 9個"));
}

#[test]
fn maximum_balance_and_overflow_rejection() {
    let text = success(&["0"], "insert 18446744073709551615\ninsert 1\nstatus\nrefund\nquit\n");
    assert!(text.contains("拒否: 残高がオーバーフローします。"));
    assert!(text.contains("残高: 18446744073709551615円 / 在庫: 0個"));
    assert!(text.contains("返金: 18446744073709551615円"));
    assert!(text.contains("終了（自動返金なし）。残高: 0円 / 在庫: 0個"));
}

#[test]
fn malformed_commands_preserve_state() {
    let text = success(&[], "insert 42\ninsert -1\ninsert +1\ninsert 18446744073709551616\ninsert abc\ninsert\nbuy extra\nunknown\n\nquit\n");
    assert_eq!(text.matches("拒否:").count(), 8, "{text}");
    assert!(text.contains("u64の範囲を超えています。"));
    assert!(text.contains("終了（自動返金なし）。残高: 42円 / 在庫: 10個"));
}

#[test]
fn invalid_initial_arguments_fail() {
    for args in [vec!["-1"], vec!["+1"], vec!["abc"], vec![""],
        vec!["18446744073709551616"], vec!["1", "2"]] {
        let output = run(&args, "");
        assert_eq!(output.status.code(), Some(1), "{args:?}");
        assert!(String::from_utf8(output.stderr).unwrap().contains("エラー:"));
        assert!(output.stdout.is_empty());
    }
}

#[test]
fn eof_does_not_refund() {
    let text = success(&["18446744073709551615"], "insert 42\n");
    assert!(text.contains("残高: 42円 / 在庫: 18446744073709551615個"));
    assert!(text.contains("入力終了（自動返金なし）。"));
    assert!(!text.contains("返金: 42円"));
}

#[test]
fn quit_does_not_refund() {
    let text = success(&[], "insert 42\nquit\n");
    assert!(text.contains("終了（自動返金なし）。残高: 42円 / 在庫: 10個"));
    assert!(!text.contains("返金: 42円"));
}
